'use strict';

const fs = require('fs');
const input = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < input.length && input[pos] <= 32) pos++;
  let value = 0;
  while (pos < input.length && input[pos] > 32) {
    value = value * 10 + input[pos] - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const head = new Int32Array(2 * N + 1);
head.fill(-1);

const edgeCount = 2 * M;
const from = new Int32Array(edgeCount);
const to = new Int32Array(edgeCount);
const next = new Int32Array(edgeCount);
const dp = new Int32Array(edgeCount);

let id = 0;

function addEdge(a, b) {
  from[id] = a;
  to[id] = b;
  next[id] = head[a + b];
  head[a + b] = id++;
}

for (let i = 0; i < M; i++) {
  const a = nextInt();
  const b = nextInt();
  addEdge(a, b);
  addEdge(b, a);
}

const best = new Int32Array(N + 1);

for (let sum = 2 * N; sum >= 2; sum--) {
  for (let e = head[sum]; e !== -1; e = next[e]) {
    const length = 1 + best[to[e]];
    dp[e] = length < 2 ? 2 : length;
  }
  for (let e = head[sum]; e !== -1; e = next[e]) {
    const a = from[e];
    if (dp[e] > best[a]) best[a] = dp[e];
  }
}

const result = new Array(N);
for (let i = 1; i <= N; i++) {
  result[i - 1] = best[i] > 0 ? best[i] : 1;
}

console.log(result.join(' '));
